def control(obs):
    m=obs['local_map']
    def interp(points,x):
        p=sorted(points)
        for a,b in zip(p,p[1:]):
            if a[0]<=x<=b[0] and b[0]-a[0]>0.01:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return None
    centers=[]
    for x in (4,8,12,16,20):
        l=interp(m['left_rail'],x); r=interp(m['right_rail'],x)
        if l is not None and r is not None: centers.append((x,(l+r)/2))
    y=sum(v*w for (x,v),w in zip(centers,[1,2,3,3,2]))/sum([1,2,3,3,2][:len(centers)]) if centers else 0
    desired=max(-22,min(22,math.degrees(math.atan2(y,12))*1.5))
    h=obs['hitch_deg']
    steer=max(-38,min(38,1.8*(h-desired)))
    return (steer,-1.0,180)

